type SafeAmount = {
  value: Int;
  invariant: value >= 0;
}

fn decrement(a: &mut SafeAmount, by: Int)
  requires: by > 0;
  requires: by <= a.value;
  ensures: a.value == a@pre.value - by;
{
  a.value = a.value - by;
}

fn main() -> Int {
  var a: SafeAmount = SafeAmount{ value: 5 };
  if 3 <= a.value {
    decrement(&mut a, 3);
  }
  return a.value;
}
